import{_ as a,o,c as i,ag as s}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Myjki ciśnieniowe","description":"","frontmatter":{},"headers":[],"relativePath":"pl/car-wash/pressure-washers.md","filePath":"pl/car-wash/pressure-washers.md"}'),n={name:"pl/car-wash/pressure-washers.md"};function r(t,e,c,d,z,p){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="myjki-cisnieniowe" tabindex="-1">Myjki ciśnieniowe <a class="header-anchor" href="#myjki-cisnieniowe" aria-label="Permalink to &quot;Myjki ciśnieniowe&quot;">​</a></h1><p>Myjki ciśnieniowe to opcja samoobsługowa: gracz parkuje, podchodzi do myjki i czyści pojazd poziom po poziomie. Płaci za każdy usunięty poziom brudu.</p><h2 id="gdzie-sie-znajduja" tabindex="-1">Gdzie się znajdują <a class="header-anchor" href="#gdzie-sie-znajduja" aria-label="Permalink to &quot;Gdzie się znajdują&quot;">​</a></h2><p>Są dwa sposoby i można używać obu jednocześnie:</p><ul><li><strong>Propy świata</strong>: każdy prop z listy <code>ManualModels</code> staje się myjką ciśnieniową, wszędzie tam, gdzie występuje na mapie. Domyślnie jest to <code>prop_gas_airunit01</code>, kompresor powietrza ze stacji benzynowych.</li><li><strong>Stanowiska, które rozmieszczasz</strong>: dodaj wpis do <code>ManualStations</code> w <code>/nay</code>, stań tam, gdzie ma się znaleźć, i naciśnij <strong>Użyj mojej pozycji</strong>.</li></ul><p>Gdy <code>ShowBlips</code> jest włączone, rozmieszczone stanowiska widać na mapie.</p><h2 id="jak-gracze-z-nich-korzystaja" tabindex="-1">Jak gracze z nich korzystają <a class="header-anchor" href="#jak-gracze-z-nich-korzystaja" aria-label="Permalink to &quot;Jak gracze z nich korzystają&quot;">​</a></h2><ul><li>Gdy <code>InteractionMode</code> ma wartość <code>key</code>, gracze podchodzą do myjki i naciskają <strong>E</strong>.</li><li>Przy <code>target</code> używają oka targetu (ox_target lub qb-target).</li></ul><p>Wyświetlany jest poziom brudu pojazdu i cena za poziom. Czyszczenie usuwa jeden poziom co <code>ManualSecondsPerLevel</code> sekund, a każdy poziom kosztuje <code>ManualPricePerLevel</code>, pobierane z konta ustawionego w <code>Account</code>. Gracze mogą przerwać w dowolnym momencie i płacą tylko za to, co wyczyścili.</p><p>Wszystkie myjki ciśnieniowe wyłączysz przez <code>ManualEnabled</code>. Wszystkie ustawienia są na stronie <a href="/pl/car-wash/settings#myjki-cisnieniowe">Ustawienia</a>.</p>',10)])])}const y=a(n,[["render",r]]);export{u as __pageData,y as default};
